<?php require_once 'functions.php';require_login();if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']??'');$qty=(int)($_POST['quantity']??0);$unit=trim($_POST['unit']??'Kg');$expiry=$_POST['expiry']??'';if($name===''||$qty<=0||!$expiry){flash('Enter item name, positive quantity and expiry date.','error');}else{$q=db()->prepare('SELECT id FROM stocks WHERE name=? AND unit=? AND expiry=?');$q->execute([$name,$unit,$expiry]);$id=$q->fetchColumn();if($id)db()->prepare('UPDATE stocks SET quantity=quantity+? WHERE id=?')->execute([$qty,$id]);else db()->prepare('INSERT INTO stocks(name,quantity,unit,expiry) VALUES(?,?,?,?)')->execute([$name,$qty,$unit,$expiry]);flash('Items successfully added to stocks.');}redirect('restock.php');}$pageTitle='Restock';$all=stocks();require 'partials/header.php'; ?><div class="restock-wrapper"><div class="restock-container panel"><h2 class="restock-title">Restock Form</h2><form method="post" class="restock-form form-grid"><input name="name" placeholder="Item name" required><input type="number" name="quantity" min="1" placeholder="Quantity" required><select name="unit"><option>Kg</option><option>L</option><option>Packets</option><option>Pieces</option></select><input type="date" name="expiry" required><button class="add-item-btn">Add Item</button></form><h2>Current Stock</h2><div class="table-wrap"><table class="restock-table"><thead><tr><th>S.No.</th><th>Name</th><th>Quantity</th><th>Expiry Date</th></tr></thead><tbody><?php foreach($all as $i=>$s):?><tr><td><?=$i+1?></td><td><?=e($s['name'])?></td><td><?=e($s['quantity'])?> <?=e($s['unit'])?></td><td><?=e($s['expiry'])?></td></tr><?php endforeach;?></tbody></table></div></div></div><?php require 'partials/footer.php'; ?>